retry.response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?mother ?motherName WHERE {
  { dbr:Sea_Sorrow dbo:director ?director . }
  UNION
  { dbr:Sea_Sorrow dbp:director ?director . }
  ?director dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherName . FILTER (lang(?motherName) = "en") }
}
LIMIT 100

